-- INACTIVE A2.1 source. Hosted installation requires separate schema/security review.
-- Existing language/reset writers and grants remain unchanged. No learner rows are touched.
begin;
create role language_legacy_evidence_executor nologin nosuperuser nocreatedb nocreaterole noreplication nobypassrls noinherit;
create role language_legacy_evidence_reset_executor nologin nosuperuser nocreatedb nocreaterole noreplication nobypassrls noinherit;
create schema language_legacy_evidence_private;
revoke all on schema language_legacy_evidence_private from public,anon,authenticated,service_role;
grant usage on schema language_legacy_evidence_private to authenticated,language_legacy_evidence_executor,language_legacy_evidence_reset_executor;
grant usage on schema public,auth to language_legacy_evidence_executor,language_legacy_evidence_reset_executor;
grant execute on function auth.uid() to language_legacy_evidence_executor,language_legacy_evidence_reset_executor;

create table public.language_legacy_evidence_manifests (
  release_id text primary key, protocol text not null, canonical_manifest text not null,
  manifest_digest text not null unique check(manifest_digest ~ '^[0-9a-f]{64}$'),
  installed_at timestamptz not null default pg_catalog.clock_timestamp(),
  unique(release_id,manifest_digest),
  check(manifest_digest=pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(canonical_manifest,'UTF8')),'hex'))
);
create table public.language_legacy_evidence_manifest_tasks (
  release_id text not null, manifest_digest text not null, task_id text not null, content_revision bigint not null,
  item_id text not null, lesson_id text not null, legacy_question_id text not null, bindings jsonb not null,
  primary key(release_id,task_id,content_revision),
  foreign key(release_id,manifest_digest) references public.language_legacy_evidence_manifests(release_id,manifest_digest),
  check(content_revision between 1 and 9007199254740991)
);
create table public.language_legacy_evidence_generations (
  owner_id uuid primary key references public.language_user_state(user_id) on delete cascade,
  generation_id uuid not null default pg_catalog.gen_random_uuid(), reset_marker jsonb,
  prospective_started_at timestamptz not null default pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp()),
  study_day_timezone text not null, protocol text not null check(protocol='legacy-evidence-server-v1'),
  last_server_sequence bigint not null default 0 check(last_server_sequence between 0 and 9007199254740991),
  unique(owner_id,generation_id)
);
create table public.language_legacy_evidence_events (
  owner_id uuid not null, generation_id uuid not null, event_id uuid not null, episode_id uuid not null,
  source_slot_key text not null, event_sequence bigint not null check(event_sequence between 0 and 9007199254740991),
  canonical_payload text not null check(pg_catalog.octet_length(canonical_payload) between 1 and 16384),
  payload jsonb not null, payload_hash text not null check(payload_hash ~ '^[0-9a-f]{64}$'),
  received_at timestamptz not null, server_sequence bigint not null check(server_sequence between 1 and 9007199254740991),
  manifest_digest text not null references public.language_legacy_evidence_manifests(manifest_digest),
  primary key(owner_id,event_id),
  foreign key(owner_id,generation_id) references public.language_legacy_evidence_generations(owner_id,generation_id) on delete cascade,
  unique(owner_id,generation_id,source_slot_key,event_sequence), unique(owner_id,generation_id,server_sequence)
);
create index language_legacy_evidence_episode_idx on public.language_legacy_evidence_events(owner_id,generation_id,episode_id,event_sequence);

alter table public.language_legacy_evidence_manifests enable row level security;
alter table public.language_legacy_evidence_manifests force row level security;
alter table public.language_legacy_evidence_manifest_tasks enable row level security;
alter table public.language_legacy_evidence_manifest_tasks force row level security;
alter table public.language_legacy_evidence_generations enable row level security;
alter table public.language_legacy_evidence_generations force row level security;
alter table public.language_legacy_evidence_events enable row level security;
alter table public.language_legacy_evidence_events force row level security;
revoke all on public.language_legacy_evidence_manifests,public.language_legacy_evidence_manifest_tasks,public.language_legacy_evidence_generations,public.language_legacy_evidence_events from public,anon,authenticated,service_role;
grant select on public.language_legacy_evidence_manifests,public.language_legacy_evidence_manifest_tasks to language_legacy_evidence_executor;
grant select,insert on public.language_legacy_evidence_generations,public.language_legacy_evidence_events to language_legacy_evidence_executor;
grant update(last_server_sequence) on public.language_legacy_evidence_generations to language_legacy_evidence_executor;
grant select(owner_id,generation_id) on public.language_legacy_evidence_generations to language_legacy_evidence_reset_executor;
grant update(generation_id,reset_marker,prospective_started_at,last_server_sequence) on public.language_legacy_evidence_generations to language_legacy_evidence_reset_executor;
grant delete on public.language_legacy_evidence_events to language_legacy_evidence_reset_executor;
grant select(owner_id,generation_id) on public.language_legacy_evidence_events to language_legacy_evidence_reset_executor;
grant select on public.language_user_state to language_legacy_evidence_executor;
-- PostgreSQL row-locking SELECT requires an UPDATE privilege; this function never writes it.
grant update(updated_at) on public.language_user_state to language_legacy_evidence_executor;
create policy legacy_evidence_language_select on public.language_user_state for select to language_legacy_evidence_executor using(auth.uid() is not null and auth.uid()=user_id);
create policy legacy_evidence_language_lock on public.language_user_state for update to language_legacy_evidence_executor using(auth.uid() is not null and auth.uid()=user_id) with check(auth.uid() is not null and auth.uid()=user_id);
create policy legacy_evidence_manifest_read on public.language_legacy_evidence_manifests for select to language_legacy_evidence_executor using(true);
create policy legacy_evidence_task_read on public.language_legacy_evidence_manifest_tasks for select to language_legacy_evidence_executor using(true);
create policy legacy_evidence_generation_read on public.language_legacy_evidence_generations for select to language_legacy_evidence_executor using(auth.uid() is not null and auth.uid()=owner_id);
-- R4 source-only correction: the private trigger can detect an enrolled owner before auth.
-- Only these two key columns are readable; every mutation remains exact-owner.
create policy legacy_evidence_reset_generation_probe on public.language_legacy_evidence_generations for select to language_legacy_evidence_reset_executor using(true);
create policy legacy_evidence_generation_insert on public.language_legacy_evidence_generations for insert to language_legacy_evidence_executor with check(auth.uid() is not null and auth.uid()=owner_id);
create policy legacy_evidence_generation_update on public.language_legacy_evidence_generations for update to language_legacy_evidence_executor,language_legacy_evidence_reset_executor using(auth.uid() is not null and auth.uid()=owner_id) with check(auth.uid() is not null and auth.uid()=owner_id);
create policy legacy_evidence_event_read on public.language_legacy_evidence_events for select to language_legacy_evidence_executor,language_legacy_evidence_reset_executor using(auth.uid() is not null and auth.uid()=owner_id);
create policy legacy_evidence_event_insert on public.language_legacy_evidence_events for insert to language_legacy_evidence_executor with check(auth.uid() is not null and auth.uid()=owner_id);
create policy legacy_evidence_event_delete on public.language_legacy_evidence_events for delete to language_legacy_evidence_reset_executor using(auth.uid() is not null and auth.uid()=owner_id);

-- Generic compact JSON canonicalizer. Integers only; no jsonb::text hashing.
create function language_legacy_evidence_private.canonical(v jsonb) returns text language plpgsql immutable security invoker set search_path='' as $$
declare t text := pg_catalog.jsonb_typeof(v); result text;
begin
  if t='object' then
    select '{'||coalesce(pg_catalog.string_agg(pg_catalog.to_jsonb(k)::text||':'||language_legacy_evidence_private.canonical(value),',' order by k collate "C"),'')||'}' into result from pg_catalog.jsonb_each(v) e(k,value);
  elsif t='array' then
    select '['||coalesce(pg_catalog.string_agg(language_legacy_evidence_private.canonical(value),',' order by n),'')||']' into result from pg_catalog.jsonb_array_elements(v) with ordinality e(value,n);
  elsif t='number' then
    if (v::text)::numeric <> pg_catalog.trunc((v::text)::numeric) or pg_catalog.abs((v::text)::numeric)>9007199254740991 then raise exception 'legacy_invalid_event'; end if;
    result := pg_catalog.trunc((v::text)::numeric)::text;
  elsif t in ('string','boolean','null') then result := v::text;
  else raise exception 'legacy_invalid_event'; end if;
  return result;
end $$;
create function language_legacy_evidence_private.instant(v timestamptz) returns text language sql immutable security invoker set search_path='' as $$
 select pg_catalog.to_char(v at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$$;
create function language_legacy_evidence_private.marker(v jsonb) returns jsonb language sql immutable security invoker set search_path='' as $$
 select pg_catalog.jsonb_build_object('present',v is not null,'value',v)
$$;
create function language_legacy_evidence_private.timezone_valid(v text) returns boolean language sql stable security invoker set search_path='' as $$
 select v is not null and pg_catalog.length(v)<=100 and (v='UTC' or
 (v ~ '^[+-][0-9]{2}:[0-9]{2}$' and v<>'-00:00' and pg_catalog.substring(v,2,2)::int<=14 and pg_catalog.substring(v,5,2)::int<=59 and (pg_catalog.substring(v,2,2)::int<14 or pg_catalog.substring(v,5,2)::int=0)) or
 (pg_catalog.strpos(v,'/')>0 and exists(select 1 from pg_catalog.pg_timezone_names z where pg_catalog.lower(z.name)=pg_catalog.lower(v))))
$$;
create function language_legacy_evidence_private.assert_request(owner uuid,digest text) returns void language plpgsql stable security invoker set search_path='' as $$
begin
 if auth.uid() is null or owner is null or owner<>auth.uid() then raise exception 'legacy_auth_mismatch' using errcode='42501'; end if;
 if digest is distinct from '139c003cd7b99e71a62dae22bd49d63524329c292bea6f953a9d1811a4045c0c' or not exists(select 1 from public.language_legacy_evidence_manifests m where m.manifest_digest=digest) then raise exception 'legacy_unsupported_manifest'; end if;
end $$;
create function language_legacy_evidence_private.context_json(g public.language_legacy_evidence_generations, at_time timestamptz) returns jsonb language sql stable security invoker set search_path='' as $$
 select pg_catalog.jsonb_build_object('ownerId',g.owner_id,'generationId',g.generation_id,'resetMarker',language_legacy_evidence_private.marker(g.reset_marker),
 'prospectiveStartedAt',language_legacy_evidence_private.instant(g.prospective_started_at),'studyDayTimezone',g.study_day_timezone,'protocol',g.protocol,
 'manifestRelease','legacy-curriculum-identity-v1','manifestDigest','139c003cd7b99e71a62dae22bd49d63524329c292bea6f953a9d1811a4045c0c',
 'serverTime',language_legacy_evidence_private.instant(at_time),'highWater',g.last_server_sequence)
$$;
create function language_legacy_evidence_private.receipt(e public.language_legacy_evidence_events) returns jsonb language sql stable security invoker set search_path='' as $$
 select pg_catalog.jsonb_build_object('ownerId',e.owner_id,'event',e.payload,'canonicalEvent',e.canonical_payload,'payloadHash',e.payload_hash,
 'receivedAt',language_legacy_evidence_private.instant(e.received_at),'serverSequence',e.server_sequence,'manifestDigest',e.manifest_digest,
 'manifestRelease',(select m.release_id from public.language_legacy_evidence_manifests m where m.manifest_digest=e.manifest_digest))
$$;

create function language_legacy_evidence_private.validate_event(raw text,owner uuid,g public.language_legacy_evidence_generations,at_time timestamptz,digest text) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare e jsonb; k text; occurred timestamptz; slot text;
 required text[]:=array['schemaVersion','eventId','generationId','episodeId','sourceSlotKey','sequence','source','lessonId','itemId','contentRevision','taskId','gradingVersion','taskFormat','occurredAt','recordTimezone','hintUsed','answerPreviouslyRevealed','isRetry','responseMs','timingComplete','audio','textVisibility','kind','correct'];
 uuid_pattern text:='^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$';
begin
 if raw is null or pg_catalog.octet_length(raw) not between 1 and 16384 then raise exception 'legacy_invalid_event'; end if;
 begin e:=raw::jsonb; exception when others then raise exception 'legacy_invalid_event'; end;
 if pg_catalog.jsonb_typeof(e) is distinct from 'object' or not(e ?& required) or e-(required||array['legacyQuestionId','lessonSessionId'])<>'{}'::jsonb or language_legacy_evidence_private.canonical(e)<>raw then raise exception 'legacy_invalid_event'; end if;
 if e->'schemaVersion'<>'1'::jsonb then raise exception 'legacy_invalid_event'; end if;
 foreach k in array array['eventId','generationId','episodeId'] loop
  if pg_catalog.jsonb_typeof(e->k)<>'string' or (e->>k)!~uuid_pattern then raise exception 'legacy_invalid_event'; end if;
 end loop;
 foreach k in array array['lessonId','itemId','taskId','gradingVersion','legacyQuestionId','lessonSessionId'] loop
  if e ? k and (pg_catalog.jsonb_typeof(e->k)<>'string' or pg_catalog.length(e->>k) not between 1 and 200 or (e->>k)!~'^[A-Za-z0-9:_@./-]+$') then raise exception 'legacy_invalid_event'; end if;
 end loop;
 foreach k in array array['sequence','contentRevision'] loop
  if pg_catalog.jsonb_typeof(e->k)<>'number' or (e->>k)!~'^(0|[1-9][0-9]*)$' or (e->>k)::numeric>9007199254740991 then raise exception 'legacy_invalid_event'; end if;
 end loop;
 if (e->>'contentRevision')::bigint<1 or e->>'generationId'<>g.generation_id::text or pg_catalog.jsonb_typeof(e->'sourceSlotKey')<>'string' or pg_catalog.length(e->>'sourceSlotKey') not between 1 and 2048 then raise exception 'legacy_invalid_event'; end if;
 if pg_catalog.jsonb_typeof(e->'source')<>'string' or e->>'source' not in ('course_lesson','course_review','item_practice') or pg_catalog.jsonb_typeof(e->'taskFormat')<>'string' or e->>'taskFormat' not in ('meaning_choice','listening_choice','typed_answer') then raise exception 'legacy_invalid_event'; end if;
 foreach k in array array['hintUsed','answerPreviouslyRevealed'] loop
  if pg_catalog.jsonb_typeof(e->k) not in ('boolean','null') then raise exception 'legacy_invalid_event'; end if;
 end loop;
 if pg_catalog.jsonb_typeof(e->'isRetry')<>'boolean' or pg_catalog.jsonb_typeof(e->'timingComplete')<>'boolean' or pg_catalog.jsonb_typeof(e->'responseMs') not in ('number','null') then raise exception 'legacy_invalid_event'; end if;
 if e->'responseMs'<>'null'::jsonb and ((e->>'responseMs')!~'^(0|[1-9][0-9]*)$' or (e->>'responseMs')::numeric>600000) then raise exception 'legacy_invalid_event'; end if;
 if (e->>'timingComplete')::boolean <> (e->'responseMs'<>'null'::jsonb) then raise exception 'legacy_invalid_event'; end if;
 if e->>'kind'='exercise_presented' then
  if e->'correct'<>'null'::jsonb or e->'sequence'<>'0'::jsonb or e->'isRetry'<>'false'::jsonb or e->'responseMs'<>'null'::jsonb or e->'timingComplete'<>'false'::jsonb then raise exception 'legacy_invalid_event'; end if;
 elsif e->>'kind'='answer_submitted' then
  if pg_catalog.jsonb_typeof(e->'correct')<>'boolean' or (e->>'sequence')::bigint<1 or (e->>'isRetry')::boolean<>((e->>'sequence')::bigint>1) then raise exception 'legacy_invalid_event'; end if;
 else raise exception 'legacy_invalid_event'; end if;
 if pg_catalog.jsonb_typeof(e->'audio')<>'object' or not((e->'audio') ?& array['status','promptMatchesTask']) or (e->'audio')-array['status','promptMatchesTask','requestId']<>'{}'::jsonb or pg_catalog.jsonb_typeof(e->'audio'->'status')<>'string' or e->'audio'->>'status' not in ('not_requested','started','completed','aborted','failed','unknown') or pg_catalog.jsonb_typeof(e->'audio'->'promptMatchesTask') not in ('boolean','null') then raise exception 'legacy_invalid_event'; end if;
 if (e->'audio') ? 'requestId' and (pg_catalog.jsonb_typeof(e->'audio'->'requestId')<>'string' or (e->'audio'->>'requestId')!~uuid_pattern) then raise exception 'legacy_invalid_event'; end if;
 if (e->'audio'->>'status' in ('started','completed','aborted','failed') and not((e->'audio')?'requestId')) or (e->'audio'->>'status'='not_requested' and ((e->'audio')?'requestId' or e->'audio'->'promptMatchesTask'<>'null'::jsonb)) then raise exception 'legacy_invalid_event'; end if;
 if pg_catalog.jsonb_typeof(e->'textVisibility')<>'object' or not((e->'textVisibility') ?& array['targetText','reading','meaning','choices']) or (e->'textVisibility')-array['targetText','reading','meaning','choices']<>'{}'::jsonb then raise exception 'legacy_invalid_event'; end if;
 foreach k in array array['targetText','reading','meaning','choices'] loop
  if pg_catalog.jsonb_typeof(e->'textVisibility'->k) not in ('boolean','null') then raise exception 'legacy_invalid_event'; end if;
 end loop;
 if e->>'source'='course_lesson' and (not(e?'lessonSessionId') or not(e?'legacyQuestionId')) or e->>'source'<>'course_lesson' and e?'lessonSessionId' or e->>'source'='course_review' and not(e?'legacyQuestionId') then raise exception 'legacy_invalid_event'; end if;
 if pg_catalog.jsonb_typeof(e->'recordTimezone')<>'string' or not language_legacy_evidence_private.timezone_valid(e->>'recordTimezone') or pg_catalog.jsonb_typeof(e->'occurredAt')<>'string' or (e->>'occurredAt')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then raise exception 'legacy_invalid_event'; end if;
 begin occurred:=(e->>'occurredAt')::timestamptz; exception when others then raise exception 'legacy_invalid_event'; end;
 if language_legacy_evidence_private.instant(occurred)<>e->>'occurredAt' or occurred<g.prospective_started_at or occurred>at_time then raise exception 'legacy_invalid_event'; end if;
 slot:=language_legacy_evidence_private.canonical(pg_catalog.jsonb_build_array('legacy-evidence-slot-v1',owner,g.generation_id,e->>'source',case when e->>'source'='course_lesson' then e->>'lessonSessionId' else e->>'episodeId' end,e->'legacyQuestionId',e->>'itemId',e->'contentRevision',e->>'taskId',e->>'taskFormat',e->>'gradingVersion'));
 if slot<>e->>'sourceSlotKey' then raise exception 'legacy_source_slot_conflict'; end if;
 if not exists(select 1 from public.language_legacy_evidence_manifest_tasks t where t.manifest_digest=digest and t.task_id=e->>'taskId' and t.content_revision=(e->>'contentRevision')::bigint and t.item_id=e->>'itemId' and t.lesson_id=e->>'lessonId' and t.legacy_question_id=e->>'legacyQuestionId' and t.bindings @> pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('source',e->>'source','taskFormat',e->>'taskFormat','gradingVersion',e->>'gradingVersion'))) then raise exception 'legacy_invalid_event'; end if;
 return e;
end $$;

create function language_legacy_evidence_private.get_context(expected_owner uuid,expected_marker jsonb,proposed_timezone text,protocol text,manifest_digest text) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' set statement_timeout='15s' as $$
declare marker jsonb; g public.language_legacy_evidence_generations;
begin
 perform language_legacy_evidence_private.assert_request(expected_owner,manifest_digest);
 if protocol is distinct from 'legacy-evidence-server-v1' then raise exception 'legacy_unsupported_protocol'; end if;
 if not language_legacy_evidence_private.timezone_valid(proposed_timezone) then raise exception 'legacy_invalid_event'; end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('app-record-reset:'||expected_owner::text,0));
 select s.state->'languageRecordResetV1' into marker from public.language_user_state s where s.user_id=expected_owner for update;
 if not found then raise exception 'legacy_state_not_ready'; end if;
 if language_legacy_evidence_private.marker(marker) is distinct from expected_marker then raise exception 'legacy_marker_conflict'; end if;
 select * into g from public.language_legacy_evidence_generations x where x.owner_id=expected_owner for update;
 if not found then
  insert into public.language_legacy_evidence_generations(owner_id,reset_marker,study_day_timezone,protocol) values(expected_owner,marker,proposed_timezone,protocol) returning * into g;
 end if;
 if g.reset_marker is distinct from marker then raise exception 'legacy_marker_conflict'; end if;
 return language_legacy_evidence_private.context_json(g,pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp()));
end $$;

create function language_legacy_evidence_private.append_events(expected_owner uuid,expected_generation uuid,manifest_digest text,batch_id uuid,source_slot text,expected_predecessor jsonb,canonical_events text[]) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' set statement_timeout='15s' as $$
declare marker jsonb; g public.language_legacy_evidence_generations; row public.language_legacy_evidence_events; head public.language_legacy_evidence_events;
 e jsonb; events jsonb[]:=array[]::jsonb[]; ids uuid[]:=array[]::uuid[]; episode uuid; i integer; n integer; known integer:=0; missing boolean:=false;
 previous_id uuid; previous_hash text; previous_sequence bigint:=-1; previous_time timestamptz; at_time timestamptz; records jsonb;
begin
 perform language_legacy_evidence_private.assert_request(expected_owner,manifest_digest);
 n:=pg_catalog.cardinality(canonical_events);
 if expected_generation is null or batch_id is null or source_slot is null or pg_catalog.length(source_slot) not between 1 and 2048 or n is null or n not between 1 and 50 or pg_catalog.array_ndims(canonical_events)<>1 or pg_catalog.array_lower(canonical_events,1)<>1 or exists(select 1 from pg_catalog.unnest(canonical_events) x where x is null or pg_catalog.octet_length(x)>16384) or (select pg_catalog.sum(pg_catalog.octet_length(x)) from pg_catalog.unnest(canonical_events) x)>262144 then raise exception 'legacy_invalid_event'; end if;
 if expected_predecessor is not null and expected_predecessor<>'null'::jsonb then
  if pg_catalog.jsonb_typeof(expected_predecessor)<>'object' or not(expected_predecessor ?& array['eventId','payloadHash','sequence']) or expected_predecessor-array['eventId','payloadHash','sequence']<>'{}'::jsonb or pg_catalog.jsonb_typeof(expected_predecessor->'eventId')<>'string' or (expected_predecessor->>'eventId')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or pg_catalog.jsonb_typeof(expected_predecessor->'payloadHash')<>'string' or (expected_predecessor->>'payloadHash')!~'^[0-9a-f]{64}$' or pg_catalog.jsonb_typeof(expected_predecessor->'sequence')<>'number' or (expected_predecessor->>'sequence')!~'^(0|[1-9][0-9]*)$' or (expected_predecessor->>'sequence')::numeric>=9007199254740991 then raise exception 'legacy_predecessor_conflict'; end if;
  previous_id:=(expected_predecessor->>'eventId')::uuid; previous_hash:=expected_predecessor->>'payloadHash'; previous_sequence:=(expected_predecessor->>'sequence')::bigint;
 end if;
 perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('app-record-reset:'||expected_owner::text,0));
 select s.state->'languageRecordResetV1' into marker from public.language_user_state s where s.user_id=expected_owner for update;
 if not found then raise exception 'legacy_state_not_ready'; end if;
 select * into g from public.language_legacy_evidence_generations x where x.owner_id=expected_owner for update;
 if not found or g.generation_id is distinct from expected_generation then raise exception 'legacy_stale_generation'; end if;
 if g.reset_marker is distinct from marker then raise exception 'legacy_marker_conflict'; end if;
 at_time:=pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp());
 if previous_id is not null then
  select * into row from public.language_legacy_evidence_events x where x.owner_id=expected_owner and x.generation_id=expected_generation and x.event_id=previous_id;
  if not found or row.payload_hash<>previous_hash or row.event_sequence<>previous_sequence or row.source_slot_key<>source_slot then raise exception 'legacy_predecessor_conflict'; end if;
  previous_time:=(row.payload->>'occurredAt')::timestamptz; episode:=row.episode_id;
 end if;
 for i in 1..n loop
  e:=language_legacy_evidence_private.validate_event(canonical_events[i],expected_owner,g,at_time,manifest_digest);
  if e->>'sourceSlotKey'<>source_slot or (episode is not null and (e->>'episodeId')::uuid<>episode) then raise exception 'legacy_source_slot_conflict'; end if;
  episode:=(e->>'episodeId')::uuid;
  if (e->>'sequence')::bigint<>previous_sequence+i then raise exception 'legacy_predecessor_conflict'; end if;
  if previous_time is not null and (e->>'occurredAt')::timestamptz<previous_time then raise exception 'legacy_invalid_event'; end if;
  previous_time:=(e->>'occurredAt')::timestamptz;
  if (e->>'eventId')::uuid=any(ids) then raise exception 'legacy_event_id_conflict'; end if;
  ids:=pg_catalog.array_append(ids,(e->>'eventId')::uuid); events:=pg_catalog.array_append(events,e);
  select * into row from public.language_legacy_evidence_events x where x.owner_id=expected_owner and x.event_id=(e->>'eventId')::uuid;
  if found then
   if row.generation_id<>expected_generation or row.canonical_payload<>canonical_events[i] or row.payload_hash<>pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(canonical_events[i],'UTF8')),'hex') or row.manifest_digest<>manifest_digest then raise exception 'legacy_event_id_conflict'; end if;
   if missing then raise exception 'legacy_predecessor_conflict'; end if;
   known:=known+1;
  else missing:=true; end if;
 end loop;
 if exists(select 1 from public.language_legacy_evidence_events x where x.owner_id=expected_owner and x.generation_id=expected_generation and ((x.episode_id=episode and x.source_slot_key<>source_slot) or (x.source_slot_key=source_slot and x.episode_id<>episode))) then raise exception 'legacy_source_slot_conflict'; end if;
 if known<n then
  select * into head from public.language_legacy_evidence_events x where x.owner_id=expected_owner and x.generation_id=expected_generation and x.source_slot_key=source_slot order by x.event_sequence desc limit 1;
  if known>0 then
   if not found or head.event_id<>ids[known] then raise exception 'legacy_predecessor_conflict'; end if;
  elsif previous_id is not null then
   if not found or head.event_id<>previous_id then raise exception 'legacy_predecessor_conflict'; end if;
  elsif found then raise exception 'legacy_source_slot_conflict'; end if;
  if g.last_server_sequence>9007199254740991-(n-known) then raise exception 'legacy_invalid_event'; end if;
  for i in (known+1)..n loop
   e:=events[i];
   insert into public.language_legacy_evidence_events(owner_id,generation_id,event_id,episode_id,source_slot_key,event_sequence,canonical_payload,payload,payload_hash,received_at,server_sequence,manifest_digest)
    values(expected_owner,expected_generation,(e->>'eventId')::uuid,episode,source_slot,(e->>'sequence')::bigint,canonical_events[i],e,pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(canonical_events[i],'UTF8')),'hex'),at_time,g.last_server_sequence+i-known,manifest_digest);
  end loop;
  update public.language_legacy_evidence_generations x set last_server_sequence=x.last_server_sequence+n-known where x.owner_id=expected_owner returning * into g;
 end if;
 select pg_catalog.jsonb_agg(language_legacy_evidence_private.receipt(x) order by ord.n) into records from pg_catalog.unnest(ids) with ordinality ord(id,n) join public.language_legacy_evidence_events x on x.owner_id=expected_owner and x.event_id=ord.id;
 return pg_catalog.jsonb_build_object('context',language_legacy_evidence_private.context_json(g,at_time),'records',records,'missingEventIds','[]'::jsonb);
end $$;

-- All read metadata and payloads below come from one statement snapshot, without row locks.
-- Function-local statement_timeout is defense in depth, not a replacement for the
-- caller/PostgREST top-level statement timer. The CI harness sets its timer before dispatch.
create function language_legacy_evidence_private.check_read(result jsonb,expected_generation uuid) returns jsonb language plpgsql immutable security invoker set search_path='' as $$
begin
 if result->'statePresent'<>'true'::jsonb then raise exception 'legacy_state_not_ready'; end if;
 if result->'context'='null'::jsonb or result->'context' is null or (expected_generation is not null and result->'context'->>'generationId'<>expected_generation::text) then raise exception 'legacy_stale_generation'; end if;
 if result->'stateMarker' is distinct from result->'context'->'resetMarker' then raise exception 'legacy_marker_conflict'; end if;
 return result-array['statePresent','stateMarker'];
end $$;
create function language_legacy_evidence_private.read_context(expected_owner uuid,expected_generation uuid,manifest_digest text) returns jsonb language plpgsql stable security definer set search_path='' set lock_timeout='5s' set statement_timeout='15s' as $$
declare result jsonb;
begin
 perform language_legacy_evidence_private.assert_request(expected_owner,manifest_digest);
 select pg_catalog.jsonb_build_object('statePresent',s.user_id is not null,'stateMarker',language_legacy_evidence_private.marker(s.state->'languageRecordResetV1'),
 'context',case when g.owner_id is not null then language_legacy_evidence_private.context_json(g,pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp())) else null end)
 into result from (values(1)) q(n) left join public.language_user_state s on s.user_id=expected_owner left join public.language_legacy_evidence_generations g on g.owner_id=s.user_id;
 return language_legacy_evidence_private.check_read(result,expected_generation)->'context';
end $$;
create function language_legacy_evidence_private.read_events(expected_owner uuid,expected_generation uuid,manifest_digest text,event_ids uuid[]) returns jsonb language plpgsql stable security definer set search_path='' set lock_timeout='5s' set statement_timeout='15s' as $$
declare result jsonb;
begin
 perform language_legacy_evidence_private.assert_request(expected_owner,manifest_digest);
 if expected_generation is null or pg_catalog.cardinality(event_ids) is null or pg_catalog.cardinality(event_ids) not between 1 and 50 or pg_catalog.array_ndims(event_ids)<>1 or pg_catalog.array_lower(event_ids,1)<>1 or exists(select 1 from pg_catalog.unnest(event_ids) id where id is null) or (select pg_catalog.count(distinct id) from pg_catalog.unnest(event_ids) id)<>pg_catalog.cardinality(event_ids) then raise exception 'legacy_invalid_event'; end if;
 with requested as materialized(select id,n from pg_catalog.unnest(event_ids) with ordinality q(id,n)), found as materialized(select q.id,q.n,e.* from requested q left join public.language_legacy_evidence_events e on e.owner_id=expected_owner and e.generation_id=expected_generation and e.event_id=q.id)
 select pg_catalog.jsonb_build_object('statePresent',s.user_id is not null,'stateMarker',language_legacy_evidence_private.marker(s.state->'languageRecordResetV1'),
 'context',case when g.owner_id is not null then language_legacy_evidence_private.context_json(g,pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp())) else null end,
 'records',coalesce((select pg_catalog.jsonb_agg(language_legacy_evidence_private.receipt(e) order by q.n) from requested q join public.language_legacy_evidence_events e on e.owner_id=expected_owner and e.generation_id=expected_generation and e.event_id=q.id),'[]'::jsonb),
 'missingEventIds',coalesce((select pg_catalog.jsonb_agg(f.id order by f.n) from found f where f.event_id is null),'[]'::jsonb))
 into result from (values(1)) q(n) left join public.language_user_state s on s.user_id=expected_owner left join public.language_legacy_evidence_generations g on g.owner_id=s.user_id;
 return language_legacy_evidence_private.check_read(result,expected_generation);
end $$;
create function language_legacy_evidence_private.read_page(expected_owner uuid,expected_generation uuid,manifest_digest text,through_sequence bigint,after_sequence bigint,page_limit integer) returns jsonb language plpgsql stable security definer set search_path='' set lock_timeout='5s' set statement_timeout='15s' as $$
declare result jsonb;
begin
 perform language_legacy_evidence_private.assert_request(expected_owner,manifest_digest);
 if expected_generation is null or through_sequence is null or after_sequence is null or page_limit is null or through_sequence not between 0 and 9007199254740991 or after_sequence not between 0 and through_sequence or page_limit not between 1 and 200 then raise exception 'legacy_invalid_event'; end if;
 with candidate as materialized(select e.*,pg_catalog.sum(pg_catalog.octet_length(e.canonical_payload)) over(order by e.server_sequence) as running_bytes from public.language_legacy_evidence_events e where e.owner_id=expected_owner and e.generation_id=expected_generation and e.server_sequence>after_sequence and e.server_sequence<=through_sequence order by e.server_sequence limit page_limit),
 chosen as materialized(select c.* from candidate c where c.running_bytes<=262144),
 boundary as (select coalesce(pg_catalog.max(c.server_sequence),after_sequence) last_seq,pg_catalog.count(*) n,coalesce(pg_catalog.sum(pg_catalog.octet_length(c.canonical_payload)),0) bytes from chosen c)
 select pg_catalog.jsonb_build_object('statePresent',s.user_id is not null,'stateMarker',language_legacy_evidence_private.marker(s.state->'languageRecordResetV1'),
 'context',case when g.owner_id is not null then language_legacy_evidence_private.context_json(g,pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp())) else null end,
 'records',coalesce((select pg_catalog.jsonb_agg(language_legacy_evidence_private.receipt(e) order by e.server_sequence) from chosen c join public.language_legacy_evidence_events e on e.owner_id=c.owner_id and e.event_id=c.event_id),'[]'::jsonb),
 'throughSequence',through_sequence,'afterSequence',after_sequence,'lastSequence',b.last_seq,'rowCount',b.n,'payloadBytes',b.bytes,'exhausted',b.last_seq=through_sequence)
 into result from (values(1)) q(n) cross join boundary b left join public.language_user_state s on s.user_id=expected_owner left join public.language_legacy_evidence_generations g on g.owner_id=s.user_id;
 result:=language_legacy_evidence_private.check_read(result,expected_generation);
 if through_sequence>(result->'context'->>'highWater')::bigint then raise exception 'legacy_invalid_event'; end if;
 return result;
end $$;

create function language_legacy_evidence_private.marker_reset() returns trigger language plpgsql security definer set search_path='' as $$
declare existing_generation uuid; locked_generation uuid;
begin
 if tg_table_schema<>'public' or tg_table_name<>'language_user_state' or tg_relid<>'public.language_user_state'::pg_catalog.regclass or tg_op<>'UPDATE' or tg_when<>'AFTER' or tg_level<>'ROW' or old.user_id is distinct from new.user_id then raise exception 'legacy_auth_mismatch' using errcode='42501'; end if;
 if old.state->'languageRecordResetV1' is not distinct from new.state->'languageRecordResetV1' then return new; end if;
 -- Already holding the language row. NEVER acquire the owner advisory lock here.
 -- Unlocked metadata-only probe preserves administrative updates for unenrolled owners.
 select x.generation_id into existing_generation from public.language_legacy_evidence_generations x where x.owner_id=new.user_id;
 if not found then return new; end if;
 if auth.uid() is null or auth.uid()<>old.user_id then raise exception 'legacy_auth_mismatch' using errcode='42501'; end if;
 select x.generation_id into locked_generation from public.language_legacy_evidence_generations x where x.owner_id=new.user_id for update;
 if not found or locked_generation is distinct from existing_generation then raise exception 'legacy_stale_generation'; end if;
 delete from public.language_legacy_evidence_events x where x.owner_id=new.user_id and x.generation_id=locked_generation;
 update public.language_legacy_evidence_generations x set generation_id=pg_catalog.gen_random_uuid(),reset_marker=new.state->'languageRecordResetV1',prospective_started_at=pg_catalog.date_trunc('milliseconds',pg_catalog.clock_timestamp()),last_server_sequence=0 where x.owner_id=new.user_id;
 if not found then raise exception 'legacy_stale_generation'; end if;
 return new;
end $$;
create trigger language_legacy_evidence_marker_reset after update of state on public.language_user_state for each row execute function language_legacy_evidence_private.marker_reset();

